"""Netact raccli"""
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase


class RacCLI(NetactBase):
    """Netact raccli"""
    def __init__(self):
        super(RacCLI, self).__init__()

    def import_(self, **kwargs):
        """Data is imported to Configurator."""
        file_name = kwargs['file_name']
        operation_type = kwargs.pop('operation_type', 'plan')
        file_format = kwargs.pop('file_format', 'RAML2')
        local_dir = kwargs.pop('local_dir', None)
        remote_file_path = kwargs.pop('remote_file_path', None)
        plan_name = kwargs.pop('plan_name', None)
        ui_values = kwargs.pop('ui_values', None)
        use_object_operation = kwargs.pop('use_object_operation', None)
        ignore_errors = kwargs.pop('ignore_errors', True)
        alias = kwargs.pop('alias', 'default')
        timeout = kwargs.pop('timeout', 7200)
        delete_plan = kwargs.get("delete_pre_exiting_plan", False)

        if remote_file_path:
            remote_file_path = remote_file_path + "/" + file_name
        if delete_plan:
            self.plan_delete(plan_name=plan_name)
        operation_object = self.netact_factory.netact.import_configuration(file_name=file_name, local_dir=local_dir,
                                                                           remote_file_path=remote_file_path,
                                                                           operation_type=operation_type,
                                                                           file_format=file_format,
                                                                           plan_name=plan_name, ui_values=ui_values,
                                                                           parameters={
                                                                               '-useObjectOperationDefinedInImportFile':
                                                                                   use_object_operation},
                                                                           ignore_errors=ignore_errors, alias=alias,
                                                                           timeout=timeout)
        return operation_object

    def plan_delete(self, **kwargs):
        """Plans are deleted from the Configurator database.
        Supported also for site templates."""
        plan_name = kwargs.pop('plan_name')
        # operation_object = self.netact_factory.raccli.plan_deletion(plan_name)
        operation_object = self.netact_factory.netact.delete_plan(plan_name=plan_name)
        # return self.netact_factory.raccli.execute_operation(operation_object, ignore_errors=ignore_errors,
        # alias=alias, timeout=timeout)
        return operation_object

    def mass_site_modification(self, **kwargs):
        """
        Site objects are created/modified and managed objects specified by the given scope are
        assigned to them. The operation scope must be defined with one or more of the following

        parameters: dist_names, working_sets, maintenance_regions or scope_dn_range.

        The operation scope is a sum of DNs retrieved from dist_names, working_sets,
            maintenance_regions and scope_dn_range.
        Operation supports:
            1. assigning managed objects given in scope to existing site identified by siteId
                parameter
            2. modifying existing site when overwrite_site_values flag is set to True and assigning
                managed objects given in scope to it,
            3. creation of new site and assigning managed objects given in scope to it.

        Parameters:
        assign_to_site (dict(string,string)): Specifies the Site to which the given scope is
            assigned. 'siteId' parameter is mandatory to create/identify the Site,
            other parameters are optional.
            If specified siteId does not exist it will be created with provided parameters.
            If the siteId already exists and overwrite_site_values parameter is set to False,
                the rest of defined parameters will be omitted.
        dist_names ((string|list(string))): Specifies the scope of the operation as exact DNs.
        working_sets ((string|list(string))): Specifies the scope of the operation as defined in
            given working sets.
        maintenance_regions ((string|list(string))): Specifies the scope of the operation as
            defined in given maintenance regions.
        scope_dn_range (string): Specifies the scope of the operation as a DN range. The range
            must include comma-separated start and end DNs of the operational objects,
            e.g. 'PLMN-PLMN/MRBTS-2500,PLMN-PLMN/MRBTS-2510'.
        object_classes ((string|list(string))): Specifies the object classes as qualified class
            abbreviation (e.g. NOKLTE:LNCEL, NOKLTE:LNBTS).
            When object_classes are given, the operation will assign to site objects that fulfill
            the following criteria:
            1. object matches the one of the given objectClasses and
            2. object belongs to the operation scope or object is the descendant of any object from
                the operation scope.
        overwrite_site_values (bool): Specifies whether site parameter values should be overwritten
            when site with provided siteId already exists.
        ui_values (bool): Specifies if parameter values are given as UI values. If this parameter
            is not defined internal values are used.

        """
        assign_to_site = kwargs["assign_to_site"]
        dist_names = kwargs.pop("dist_names", None)
        working_sets = kwargs.pop("working_sets", None)
        maintenance_regions = kwargs.pop("maintenance_regions", None)
        scope_dn_range = kwargs.pop("scope_dn_range", None)
        object_classes = kwargs.pop("object_classes", None)
        overwrite_site_values = kwargs.pop("overwrite_site_values", False)
        ui_values = kwargs.pop("ui_values", None)
        timeout = kwargs.pop('timeout', 7200)
        alias = kwargs.pop("alias", None)
        # return self.netact_factory.raccli.mass_site_modification(
        #     assign_to_site, dist_names=dist_names,
        #     working_sets=working_sets, maintenance_regions=maintenance_regions,
        #     scope_dn_range=scope_dn_range, object_classes=object_classes,
        #     overwrite_site_values=overwrite_site_values,
        #     ui_values=ui_values)
        return self.netact_factory.netact.modify_mass_site(
            assign_to_site=assign_to_site, dist_names=dist_names,
            working_sets=working_sets, maintenance_regions=maintenance_regions,
            scope_dn_range=scope_dn_range, object_classes=object_classes,
            overwrite_site_values=overwrite_site_values,
            ui_values=ui_values, timeout=timeout, alias=alias)
